{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room for two people by ensuring refreshment settings are near chairs and entertainment control is accessible.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_set",
        "entity_kind": "OBJECT",
        "function": "Provides drink and food for one person",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": [ "cup", "plate", "snack_container" ],
        "required_properties": [ "holds_food_or_drink" ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Controls the television",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": [ "remote_control" ],
        "required_properties": [ "has_buttons", "wireless" ]
      },
      {
        "id": "seating_area",
        "entity_kind": "REGION",
        "function": "Reference point for 'nearby' placement",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": [ "armchair", "couch" ],
        "required_properties": [ "has_seat" ]
      },
      {
        "id": "central_surface",
        "entity_kind": "OBJECT",
        "function": "Accessible destination for shared items",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [ "coffee_table", "side_table" ],
        "required_properties": [ "flat_surface" ]
      }
    ],
    "functional_relations": [
      {
        "id": "rel_refreshment_near_seat",
        "relation": "located_near",
        "participant_roles": [ "refreshment_set", "seating_area" ],
        "required": true
      },
      {
        "id": "rel_control_accessible",
        "relation": "accessible_to",
        "participant_roles": [ "entertainment_control", "seating_area", "seating_area" ],
        "required": true
      }
    ],
    "operation_pairings": []
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_set": [
        { "label": "red_cup", "visual_description": "Red mug on table" },
        { "label": "white_plate", "visual_description": "White plate on table" }
      ],
      "entertainment_control": [
        { "label": "black_remote", "visual_description": "Black remote on table" }
      ],
      "seating_area": [
        { "label": "wooden_armchair", "visual_description": "Wooden chair with black cushion" },
        { "label": "wooden_armchair", "visual_description": "Wooden chair with black cushion" }
      ],
      "central_surface": [
        { "label": "coffee_table", "visual_description": "Wooden coffee table" }
      ]
    },
    "inspectable_regions": [
      {
        "id": "under_coffee_table",
        "label": "Under Coffee Table Storage",
        "visual_description": "Closed drawer or cubby underneath the table",
        "reason": "Could contain additional refreshment supplies or alternative storage for the remote."
      },
      {
        "id": "under_console",
        "label": "Under Console Storage",
        "visual_description": "Space beneath the TV console",
        "reason": "Could contain spare remotes or power controls."
      }
    ],
    "inspection_order": [ "under_coffee_table", "under_console" ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
